bootforge/ts-basics/type-annotations/int.solution:
interface Line {
  description: string;
  qty: number;
  unitCents: number;
}

interface Invoice {
  customer: string;
  lines: Line[];
  taxRate: number;
}

export function invoiceTotal(inv: Invoice): { subtotalCents: number; taxCents: number; totalCents: number } {
  let subtotalCents = 0;
  for (const line of inv.lines) {
    subtotalCents += line.qty * line.unitCents;
  }
  const taxCents = Math.round(subtotalCents * inv.taxRate);
  return { subtotalCents, taxCents, totalCents: subtotalCents + taxCents };
}

