bootforge/ts-basics/type-annotations/arr.solution:
export function scoreboard(entries: [string, number][]): { winner: string; totalPoints: number; average: number } {
  let winner = entries[0][0];
  let best = entries[0][1];
  let totalPoints = 0;
  for (const [name, points] of entries) {
    totalPoints += points;
    if (points > best) {
      best = points;
      winner = name;
    }
  }
  return { winner, totalPoints, average: Math.round(totalPoints / entries.length) };
}

