export function totalColumn(cells: (number | string | null)[]): number {
  let total = 0;
  for (const cell of cells) {
    if (cell === null) continue;
    if (typeof cell === 'number') {
      total += cell;
      continue;
    }
    const parsed = Number.parseFloat(cell);
    if (!Number.isNaN(parsed)) total += parsed;
  }
  return total;
}

