type Direction = 'north' | 'south' | 'east' | 'west';

const DELTAS: Record<Direction, [number, number]> = {
  north: [0, 1],
  south: [0, -1],
  east: [1, 0],
  west: [-1, 0],
};

export function movePoint(p: [number, number], dir: Direction): [number, number] {
  const [dx, dy] = DELTAS[dir];
  return [p[0] + dx, p[1] + dy];
}

