bootforge/ts-basics/unions-narrowing/typ.solution:
type User = { id: number; username: string };
type Post = { id: number; authorId: number; title: string; status: 'draft' | 'published' };
type Comment = { id: number; postId: number; text: string };

export function blogStats(users: User[], posts: Post[], comments: Comment[]): { userCount: number; publishedCount: number; draftCount: number; commentsPerPost: number; topAuthor: string | null } {
  const published = posts.filter((p) => p.status === 'published');
  const draftCount = posts.length - published.length;

  const byAuthor: Record<number, number> = {};
  let topAuthorId: number | null = null;
  let best = 0;
  for (const p of published) {
    byAuthor[p.authorId] = (byAuthor[p.authorId] ?? 0) + 1;
    if (byAuthor[p.authorId] > best) {
      best = byAuthor[p.authorId];
      topAuthorId = p.authorId;
    }
  }

  const topUser = topAuthorId === null ? null : users.find((u) => u.id === topAuthorId) ?? null;

  return {
    userCount: users.length,
    publishedCount: published.length,
    draftCount,
    commentsPerPost: published.length === 0 ? 0 : Math.round(comments.length / published.length),
    topAuthor: topUser === null ? null : topUser.username,
  };
}
